const req = $input.first().json;
const query = req.query || {};
const body = req.body || {};

// --- Webhook verification (GET request from Facebook) ---
// n8n may structure query params as nested objects (hub.mode -> hub: { mode })
// or as flat keys, so we check both
const hubMode = (query.hub && query.hub.mode) || query['hub.mode'];
const hubVerifyToken = (query.hub && query.hub.verify_token) || query['hub.verify_token'];
const hubChallenge = (query.hub && query.hub.challenge) || query['hub.challenge'];

if (hubMode === 'subscribe') {
  const verifyToken = "PASTE_YOUR_FB_VERIFY_TOKEN_HERE";
  if (hubVerifyToken === verifyToken) {
    return [{ json: { routeType: 'verify', challenge: String(hubChallenge || '') } }];
  }
  return [{ json: { routeType: 'verify_failed', challenge: '' } }];
}

// --- Signature verification ---
// NOTE: Disabled because n8n does not expose the raw request body.
// JSON.stringify(body) may produce different bytes than the original
// request, causing HMAC mismatches. Facebook messages will still work
// without signature verification.

// --- Parse incoming message/postback ---
const entry = body.entry;
if (!entry || !entry[0] || !entry[0].messaging || !entry[0].messaging[0]) {
  return [{ json: { routeType: 'ignore', reason: 'No messaging data' } }];
}

const messaging = entry[0].messaging[0];
const senderId = messaging.sender?.id || '';
const recipientId = messaging.recipient?.id || '';

let messageText = '';
let routeType = 'message';

if (messaging.postback) {
  messageText = messaging.postback.payload || '';
  routeType = messaging.postback.payload === 'GET_STARTED' ? 'get_started' : 'postback';
} else if (messaging.message) {
  if (messaging.message.quick_reply) {
    messageText = messaging.message.quick_reply.payload || messaging.message.text || '';
    routeType = 'quick_reply';
  } else if (messaging.message.text) {
    messageText = messaging.message.text;
    routeType = 'message';
  } else {
    messageText = '';
    routeType = 'unsupported';
  }
}

// Sanitize
messageText = String(messageText).replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '').trim();
if (messageText.length > 2000) messageText = messageText.substring(0, 2000);

return [{
  json: {
    routeType,
    senderId,
    recipientId,
    messageText,
    sessionId: 'fb_' + senderId,
    chatInput: messageText || 'Sveiki'
  }
}];

