        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + accessToken
        },
        body: JSON.stringify(msg)
      }
    );

    const data = await response.json();

    if (!response.ok) {
      console.error('FB API error: ' + response.status + ' ' + JSON.stringify(data));
    }

    results.push({ success: response.ok, status: response.status, data });

    // Small delay between messages to maintain order
    if (i < messages.length - 1) {
      await new Promise(resolve => setTimeout(resolve, 300));
    }
  } catch (error) {
    console.error('FB API fetch error: ' + error.message);
    results.push({ success: false, error: error.message });
  }
}

return [{ json: { sent: results.length, results } }];
